// One item per PDF attachment, with the PDF in the binary field "data". The mail's facts travel along.
const cfg = $('Config').first().json;
const out = [];
for (const mail of $('Gmail Trigger').all()) {
  const keys = Object.keys(mail.binary ?? {});
  let idx = 0;
  for (const k of keys) {
    const b = mail.binary[k];
    const isPdf = /pdf/i.test(b.mimeType ?? '') || /\.pdf$/i.test(b.fileName ?? '');
    if (!isPdf) continue;
    out.push({ json: { message_id: mail.json.id, att_index: idx++, source_file: b.fileName ?? k, mail_from: mail.json.from?.text ?? mail.json.from ?? '',
      subject: mail.json.subject ?? '', received_at: mail.json.date ?? '' }, binary: { data: b } });
  }
}
return out;

// ---- guard for AI-read receipts ----------------------------------------------------------
const nfkc = (s) => String(s ?? '').normalize('NFKC');
const norm = (s) => nfkc(s).replace(/[‘’‛]/g, "'").replace(/[“”]/g, '"').replace(/[‐-―−]/g, '-').toLowerCase();
const squash = (s) => norm(s).replace(/\s+/g, '');
// a number, also when it arrives as text with a currency mark ("¥3,200", "3,200円")
const num = (v) => { const s = nfkc(v).replace(/[,\s¥￥$円]/g, ''); const n = Number(s); return Number.isFinite(n) && s !== '' ? n : NaN; };
// a short stable hash (cyrb53)
function hash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) { const c = str.charCodeAt(i); h1 = Math.imul(h1 ^ c, 2654435761); h2 = Math.imul(h2 ^ c, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}
const isoOf = (y, m, d) => { const t = new Date(Date.UTC(y, m - 1, d)); return t.getUTCFullYear() === y && t.getUTCMonth() === m - 1 && t.getUTCDate() === d ? t.toISOString().slice(0, 10) : ''; };
const dayNo = (iso) => Math.round(new Date(iso + 'T00:00:00Z').getTime() / 86400000);

// every number written in the document text
function numbersIn(text) {
  return (nfkc(text).replace(/(?<=\d),(?=\d{3}(?!\d))/g, '').match(/\d+(?:\.\d+)?/g) ?? []).map(Number);
}

// PDF text can hold look-alike forms of Japanese characters (a radical or a variant form instead of the usual character), so a name of 5+
// characters may differ in up to one character in five. Amounts and numbers are never checked loosely.
function containsLoose(src, needle) {
  if (src.includes(needle)) return true;
  const n = needle.length;
  if (n < 5) return false;
  const need = Math.ceil(n * 0.8);
  for (let i = 0; i + n <= src.length; i++) {
    let same = 0;
    for (let j = 0; j < n; j++) if (src[i + j] === needle[j]) same++;
    if (same >= need) return true;
  }
  return false;
}

// meta = { text, source_file, mail_from, subject, received_at, message_id, att_index, base_currency, today }
function checkReceipt(raw, meta) {
  const tol = 1; // rounding of tax / unit prices
  let ai = null;
  try {
    const t = String(raw ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
    const a = t.indexOf('{'), z = t.lastIndexOf('}');
    ai = JSON.parse(a >= 0 && z > a ? t.slice(a, z + 1) : t);
  } catch (e) { ai = null; }
  const problems = [];
  if (!ai) problems.push('the AI output could not be read as JSON');
  ai = ai ?? {};

  const text = String(meta.text ?? '');
  const src = squash(text);
  const hasText = src.length >= 20;
  const nums = hasText ? numbersIn(text) : [];
  const written = (n) => nums.some((x) => Math.abs(x - n) < 0.005);

  const vendor = String(ai.vendor ?? '').trim();
  const docNo = String(ai.document_no ?? '').trim();
  const total = num(ai.total);
  const date = /^\d{4}-\d{2}-\d{2}$/.test(String(ai.issue_date ?? '')) ? isoOf(...String(ai.issue_date).split('-').map(Number)) : '';
  const currency = String(ai.currency ?? '').trim().toUpperCase() || meta.base_currency;
  const lines = (Array.isArray(ai.lines) ? ai.lines : []).filter((l) => l && typeof l === 'object');
  const taxes = (Array.isArray(ai.tax) ? ai.tax : []).filter((t) => t && typeof t === 'object');

  if (!vendor) problems.push('the vendor is missing');
  if (!date) problems.push('the issue date is missing or not a date');
  if (!(total > 0)) problems.push('the total is missing');

  // 1. is it written in the document?
  if (!hasText) problems.push('no text layer (a scan or a photo): the values could not be checked against the text');
  else {
    if (vendor && !containsLoose(src, squash(vendor))) problems.push('the vendor name is not in the document text');
    if (docNo && !src.includes(squash(docNo))) problems.push('the document number is not in the document text');
    if (total > 0 && !written(total)) problems.push('the total ' + total + ' is not written in the document');
    if (date) {
      const [y, m, d] = date.split('-').map(Number);
      if (!new RegExp(y + '\\s*[-/.年]\\s*0?' + m + '\\s*[-/.月]\\s*0?' + d + '(?!\\d)').test(nfkc(text))) problems.push('the issue date is not written in the document');
    }
    lines.forEach((l, i) => { const a = num(l.amount); if (Number.isFinite(a) && !written(a)) problems.push('line ' + (i + 1) + ': the amount ' + a + ' is not written in the document'); });
    taxes.forEach((t) => { const a = num(t.amount); if (Number.isFinite(a) && !written(a)) problems.push('the tax amount ' + a + ' is not written in the document'); });
  }

  // 2. does it add up? (code does the arithmetic, not the AI)
  const sumLines = lines.reduce((s, l) => s + (num(l.amount) || 0), 0);
  const taxTotal = taxes.reduce((s, t) => s + (num(t.amount) || 0), 0);
  lines.forEach((l, i) => {
    const q = num(l.quantity), u = num(l.unit_price), a = num(l.amount);
    if ([q, u, a].every(Number.isFinite) && Math.abs(q * u - a) > tol) problems.push('line ' + (i + 1) + ': ' + q + ' x ' + u + ' is not ' + a);
  });
  let taxMode = 'unknown';
  if (lines.length && total > 0) {
    const excl = Math.abs(sumLines + taxTotal - total) <= tol;
    const incl = Math.abs(sumLines - total) <= tol;
    taxMode = excl && taxTotal > 0 ? 'added' : incl ? 'included' : excl ? 'none' : 'unknown';
    if (!excl && !incl) problems.push('the lines and tax do not add up to the total (lines ' + sumLines + ', tax ' + taxTotal + ', total ' + total + ')');
    const sub = num(ai.subtotal);
    if (Number.isFinite(sub) && Math.abs(sub - sumLines) > tol) problems.push('the subtotal ' + sub + ' is not the sum of the lines (' + sumLines + ')');
    if ((excl || incl) && taxes.length === 1 && num(taxes[0].rate_percent) > 0) {
      const r = num(taxes[0].rate_percent);
      const expected = taxMode === 'added' ? (sumLines * r) / 100 : (total * r) / (100 + r);
      if (Math.abs(expected - taxTotal) > tol + 0.01) problems.push('the tax ' + taxTotal + ' does not match ' + r + '% (expected about ' + Math.round(expected) + ')');
    }
  }

  // 3. is the date believable?
  if (date && meta.today) {
    const age = dayNo(meta.today) - dayNo(date);
    if (age < -1) problems.push('the issue date is in the future');
    if (age > 800) problems.push('the issue date is more than 800 days ago');
  }

  // payment method: "cash" counts only when the document says so
  let pay = String(ai.payment_method ?? '').toLowerCase();
  if (!['card', 'cash', 'bank_transfer', 'unknown'].includes(pay)) pay = 'unknown';
  if (pay === 'cash' && hasText && !/現金|cash/.test(norm(text))) { pay = 'unknown'; problems.push('the AI said cash, but the document does not say so'); }

  const receiptId = 'rc-' + hash(squash(vendor) + '|' + squash(docNo) + '|' + date + '|' + (Number.isFinite(total) ? total : ''));
  return {
    row_id: receiptId + '@' + String(meta.message_id ?? '') + '-' + (meta.att_index ?? 0), receipt_id: receiptId,
    status: problems.length ? 'Needs review' : 'OK', problems: problems.join('; '),
    vendor, doc_type: String(ai.document_type ?? ''), doc_no: docNo, issue_date: date, currency,
    subtotal: Number.isFinite(num(ai.subtotal)) ? num(ai.subtotal) : '', tax_total: taxes.length ? taxTotal : '', total: Number.isFinite(total) ? total : '',
    payment_method: pay, text_check: hasText ? 'checked against text' : 'no text layer',
    lines: lines.map((l) => [l.description, l.quantity, l.unit_price, l.amount].join(' | ')).join(' ; '),
    source_file: meta.source_file ?? '', mail_from: meta.mail_from ?? '', subject: meta.subject ?? '', received_at: meta.received_at ?? '',
  };
}

const cfg = $('Config').first().json;
const meta0 = $('Split attachments').all();
const text = $('Extract text from PDF').all();
const today = $now.toFormat('yyyy-MM-dd');
return $input.all().map((it, i) => {
  const m = meta0[i].json;
  const raw = it.json.content?.[0]?.text ?? it.json.text;
  return { json: checkReceipt(raw, { ...m, text: text[i]?.json?.text ?? '', base_currency: cfg.base_currency, today }) };
});

// ---- matching the card statement with the receipts (no AI) --------------------------------
const nfkc = (s) => String(s ?? '').normalize('NFKC');
const norm = (s) => nfkc(s).replace(/[‘’‛]/g, "'").replace(/[“”]/g, '"').replace(/[‐-―−]/g, '-').toLowerCase();
const squash = (s) => norm(s).replace(/\s+/g, '');
// a number, also when it arrives as text with a currency mark ("¥3,200", "3,200円")
const num = (v) => { const s = nfkc(v).replace(/[,\s¥￥$円]/g, ''); const n = Number(s); return Number.isFinite(n) && s !== '' ? n : NaN; };
// a short stable hash (cyrb53)
function hash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) { const c = str.charCodeAt(i); h1 = Math.imul(h1 ^ c, 2654435761); h2 = Math.imul(h2 ^ c, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}
const isoOf = (y, m, d) => { const t = new Date(Date.UTC(y, m - 1, d)); return t.getUTCFullYear() === y && t.getUTCMonth() === m - 1 && t.getUTCDate() === d ? t.toISOString().slice(0, 10) : ''; };
const dayNo = (iso) => Math.round(new Date(iso + 'T00:00:00Z').getTime() / 86400000);

function parseCardDate(v) {
  // a spreadsheet date read as a serial number (days since 1899-12-30): the same in every locale
  if (/^\d{5}(\.\d+)?$/.test(String(v).trim()) && Number(v) > 20000 && Number(v) < 80000) return new Date(Date.UTC(1899, 11, 30) + Math.floor(Number(v)) * 86400000).toISOString().slice(0, 10);
  const s = nfkc(v).trim();
  let m = s.match(/(\d{4})\s*[-\/.年]\s*(\d{1,2})\s*[-\/.月]\s*(\d{1,2})/);
  return m ? isoOf(+m[1], +m[2], +m[3]) : '';
}
function parseAmount(v) {
  let s = nfkc(v).trim();
  if (!s) return NaN;
  const neg = /^[(▲△-]/.test(s) || /-$/.test(s) || /^−/.test(s);
  s = s.replace(/[¥￥円,\s()▲△\-−]/g, '');
  const n = Number(s);
  return Number.isFinite(n) && s !== '' ? (neg ? -n : n) : NaN;
}
// how alike two names are (character pairs). Names in different scripts (ABC vs カタカナ) score 0: the score is only a tie-breaker.
function nameScore(a, b) {
  const grams = (s) => { const t = squash(s).replace(/[^\p{L}\p{N}]/gu, ''); const g = new Set(); for (let i = 0; i < t.length - 1; i++) g.add(t.slice(i, i + 2)); return g; };
  const A = grams(a), B = grams(b);
  if (!A.size || !B.size) return 0;
  let both = 0; for (const x of A) if (B.has(x)) both++;
  return both / (A.size + B.size - both);
}
const yen = (n) => (Math.abs(n) % 1 === 0 ? String(n) : n.toFixed(2));

// receipts = Receipts-tab rows, card = Card-tab rows, cfg = { date_col, vendor_col, amount_col, base_currency, days_before, days_after, near_pct, tolerance }
function matchStatement(receipts, card, cfg) {
  const out = [];
  const daysBefore = Number(cfg.days_before) || 0, daysAfter = Number(cfg.days_after) || 0, tol = Number(cfg.tolerance) || 0, nearPct = Number(cfg.near_pct) || 0;

  // receipts: the first one that arrived is the main one, later copies are duplicates
  const rows = receipts.filter((r) => r.row_id && r.receipt_id).map((r) => ({ ...r, issue_date: parseCardDate(r.issue_date) || String(r.issue_date ?? '') })).sort((a, b) => String(a.received_at).localeCompare(String(b.received_at)) || String(a.row_id).localeCompare(String(b.row_id)));
  const firstOf = new Map();
  const main = [];
  for (const r of rows) {
    if (!firstOf.has(r.receipt_id)) { firstOf.set(r.receipt_id, r); main.push(r); }
    else out.push({ match_key: 'receipt:' + r.row_id, kind: 'receipt', status: 'Duplicate receipt', receipt_id: r.row_id, receipt_vendor: r.vendor, receipt_date: r.issue_date, receipt_total: r.total,
      note: 'the same document as ' + firstOf.get(r.receipt_id).row_id + ' (same vendor, number, date and total); it is not matched' });
  }
  const eligible = main.filter((r) => String(r.currency || cfg.base_currency) === cfg.base_currency && r.payment_method !== 'cash' && num(r.total) > 0 && /^\d{4}-\d{2}-\d{2}$/.test(String(r.issue_date)));
  const taken = new Map(); // receipt row_id -> card line id

  // the card lines
  const seen = new Map();
  const lines = [];
  card.forEach((row, i) => {
    const date = parseCardDate(row[cfg.date_col]);
    const vendor = String(row[cfg.vendor_col] ?? '').trim();
    const amount = parseAmount(row[cfg.amount_col]);
    if (!vendor && !String(row[cfg.date_col] ?? '').trim() && !String(row[cfg.amount_col] ?? '').trim()) return; // an empty row
    const base = date + '|' + squash(vendor) + '|' + amount;
    const n = (seen.get(base) ?? 0) + 1; seen.set(base, n);
    lines.push({ id: 'cl-' + hash(base) + '#' + n, date, vendor, amount, row: i + 2 });
  });
  const diffOf = (l, r) => dayNo(l.date) - dayNo(r.issue_date);
  const inWindow = (l, r) => { const d = diffOf(l, r); return d >= -daysBefore && d <= daysAfter; };
  const candidatesOf = (l) => eligible.filter((r) => !taken.has(r.row_id) && Math.abs(num(r.total) - l.amount) <= tol && inWindow(l, r));

  const ok = lines.filter((l) => l.date && Number.isFinite(l.amount) && l.amount > 0).sort((a, b) => a.date.localeCompare(b.date) || a.row - b.row);
  const result = new Map();
  let changed = true;
  while (changed) {
    changed = false;
    for (const l of ok) {
      if (result.has(l.id)) continue;
      const c = candidatesOf(l);
      let pick = null, how = '';
      if (c.length === 1) { pick = c[0]; how = 'only one receipt has this amount in the date window'; }
      else if (c.length > 1) {
        const sc = c.map((r) => ({ r, s: nameScore(l.vendor, r.vendor) })).sort((a, b) => b.s - a.s);
        if (sc[0].s >= 0.3 && sc[0].s - sc[1].s >= 0.2) { pick = sc[0].r; how = 'several receipts had this amount; the vendor name decided'; }
      }
      if (pick) { taken.set(pick.row_id, l.id); result.set(l.id, { pick, how }); changed = true; }
    }
  }

  const matched = [];
  const ambiguousFor = new Map();
  for (const l of lines) {
    const base = { match_key: 'card:' + l.id, kind: 'card', card_date: l.date, card_vendor: l.vendor, card_amount: Number.isFinite(l.amount) ? l.amount : '' };
    const hit = result.get(l.id);
    if (!l.date || !Number.isFinite(l.amount)) { out.push({ ...base, status: 'Card line not understood', note: 'row ' + l.row + ': the date or the amount could not be read (dates need the year first, like 2026-09-05)' }); continue; }
    if (l.amount <= 0) { out.push({ ...base, status: 'Refund or credit', note: 'a negative amount is not matched' }); continue; }
    if (hit) {
      const r = hit.pick;
      matched.push(l);
      out.push({ ...base, status: 'Matched', receipt_id: r.row_id, receipt_vendor: r.vendor, receipt_date: r.issue_date, receipt_total: num(r.total), day_diff: diffOf(l, r),
        note: hit.how + (r.status === 'Needs review' ? '. The receipt itself needs review: ' + r.problems : '') });
      continue;
    }
    const c = candidatesOf(l);
    if (c.length > 1) { for (const r of c) ambiguousFor.set(r.row_id, l); out.push({ ...base, status: 'Ambiguous', note: 'choose one: ' + c.map((r) => r.row_id + ' (' + r.vendor + ', ' + r.issue_date + ')').join(' / ') }); continue; }
    // the same charge twice? an earlier matched line with the same shop and amount a few days apart
    const twin = lines.find((o) => o.id !== l.id && result.has(o.id) && o.amount === l.amount && squash(o.vendor) === squash(l.vendor) && Math.abs(dayNo(o.date) - dayNo(l.date)) <= 3);
    if (twin) { out.push({ ...base, status: 'Possible double charge', note: 'same shop and amount as ' + twin.id + ' (' + twin.date + '), and there is only one receipt' }); continue; }
    const near = eligible.filter((r) => !taken.has(r.row_id) && inWindow(l, r) && Math.abs(num(r.total) - l.amount) / num(r.total) <= nearPct / 100 && Math.abs(num(r.total) - l.amount) > tol);
    if (near.length) { out.push({ ...base, status: 'Near match', note: 'no exact amount; close: ' + near.map((r) => r.row_id + ' (' + r.vendor + ' ' + yen(num(r.total)) + ', ' + r.issue_date + ')').join(' / ') }); continue; }
    const foreign = main.filter((r) => String(r.currency || cfg.base_currency) !== cfg.base_currency && /^\d{4}-\d{2}-\d{2}$/.test(String(r.issue_date)) && inWindow(l, r));
    out.push({ ...base, status: 'No receipt', note: foreign.length ? 'no receipt in ' + cfg.base_currency + '. Foreign-currency receipt(s) in the window: ' + foreign.map((r) => r.row_id + ' (' + r.vendor + ' ' + r.currency + ' ' + yen(num(r.total)) + ', ' + r.issue_date + ')').join(' / ') : 'no receipt has this amount in the date window' });
  }

  // receipts nobody claimed
  for (const r of main) {
    if (taken.has(r.row_id)) continue;
    const base = { match_key: 'receipt:' + r.row_id, kind: 'receipt', receipt_id: r.row_id, receipt_vendor: r.vendor, receipt_date: r.issue_date, receipt_total: num(r.total) };
    if (ambiguousFor.has(r.row_id)) out.push({ ...base, status: 'Ambiguous', note: 'one of the candidates for the card line ' + ambiguousFor.get(r.row_id).date + ' ' + ambiguousFor.get(r.row_id).vendor + ' ' + ambiguousFor.get(r.row_id).amount });
    else if (String(r.currency || cfg.base_currency) !== cfg.base_currency) out.push({ ...base, status: 'Receipt only', note: 'foreign currency (' + r.currency + '): not matched automatically' });
    else if (r.payment_method === 'cash') out.push({ ...base, status: 'Receipt only', note: 'paid in cash: not expected on the card statement' });
    else if (!/^\d{4}-\d{2}-\d{2}$/.test(String(r.issue_date)) || !(num(r.total) > 0)) out.push({ ...base, status: 'Receipt only', note: 'the date or the total is missing, so it cannot be matched' });
    else out.push({ ...base, status: 'Receipt only', note: 'no card line has this amount in the date window (not posted yet, or paid another way)' });
  }
  const order = ['Ambiguous', 'No receipt', 'Possible double charge', 'Near match', 'Card line not understood', 'Receipt only', 'Duplicate receipt', 'Refund or credit', 'Matched'];
  out.sort((a, b) => order.indexOf(a.status) - order.indexOf(b.status));
  return out;
}

function summarize(rows) {
  const count = {};
  for (const r of rows) count[r.status] = (count[r.status] ?? 0) + 1;
  const need = rows.filter((r) => r.kind === 'card' && ['Ambiguous', 'No receipt', 'Possible double charge', 'Near match', 'Card line not understood'].includes(r.status));
  const head = '*Card statement check* - ' + Object.entries(count).map(([k, v]) => k + ': ' + v).join(', ');
  const body = need.slice(0, 15).map((r) => '• ' + r.status + ': ' + r.card_date + ' ' + r.card_vendor + ' ' + r.card_amount + (r.note ? ' - ' + r.note : '')).join('\n');
  return head + (body ? '\n' + body : '') + (need.length > 15 ? '\n• ... and ' + (need.length - 15) + ' more (see the Matches tab)' : '');
}

const cfg = $('Config').first().json;
const receipts = $('Read Receipts tab').all().map((i) => i.json);
const card = $('Read Card tab').all().map((i) => i.json);
// a wrong column name would make every card line look empty and be skipped without a word: stop with a clear message instead
const cols = { date_col: cfg.card_date_col, vendor_col: cfg.card_vendor_col, amount_col: cfg.card_amount_col };
if (card.length) {
  const have = Object.keys(card[0]);
  const missing = Object.entries(cols).filter(([, c]) => !have.includes(c)).map(([, c]) => '"' + c + '"');
  if (missing.length) throw new Error('The Card tab has no column named ' + missing.join(', ') + '. Columns found: ' + have.filter((k) => k !== 'row_number').join(', ') + '. Change card_date_col / card_vendor_col / card_amount_col in Config.');
}
const rows = matchStatement(receipts, card, { ...cfg, ...cols });
if (!rows.length) rows.push({ match_key: 'note', kind: 'note', status: 'Nothing to match', note: 'the Card tab and the Receipts tab are both empty' });
return rows.map((r) => ({ json: r }));

